from pwn import *

# Load the binary
elf = ELF("./ctf_files/beleaf")

# Get the tree nodes from DAT_00301020
tree_nodes = []
for i in range(100):  # Read enough nodes to cover the tree
    try:
        value = elf.read(0x301020 + i * 4, 4)
        value = u32(value)
        tree_nodes.append(value)
    except:
        break

# Get expected traversal results from DAT_003014e0
expected_paths = []
for i in range(33):  # Flag length is at least 33 chars
    try:
        value = elf.read(0x3014e0 + i * 8, 8)
        value = u64(value)
        expected_paths.append(value)
    except:
        break

def find_char_for_path(target_path):
    # Try all printable ASCII characters
    for c in range(32, 127):
        current = 0
        while current != -1 and c != tree_nodes[current]:
            if c < tree_nodes[current]:
                current = current * 2 + 1
            elif c > tree_nodes[current]:
                current = (current + 1) * 2
        if current == target_path:
            return chr(c)
    return None

# Reconstruct the flag
flag = ""
for path in expected_paths:
    char = find_char_for_path(path)
    if char:
        flag += char
    else:
        print(f"Could not find character for path {path}")

print("Reconstructed flag:", flag)
# Verify flag format
assert len(flag) == 33
assert flag.startswith("flag{")
assert flag.endswith("}")

