#!/usr/bin/env python3
from pwn import *

# Load the binary
binary = ELF('./ctf_files/beleaf')

# Get the base address for the data sections
dat_tree = binary.get_section_by_name('.data').header.sh_addr
dat_expected = binary.get_section_by_name('.data').header.sh_addr + 0x4c0  # 0x3014e0 - 0x301020

# Extract tree nodes and expected traversal results
tree_nodes = []
expected_paths = []

# Read tree nodes (array of ints)
for i in range(128):  # Large enough to cover the tree
    tree_nodes.append(u32(binary.read(dat_tree + i*4, 4)))

# Read expected paths (array of longs)
for i in range(33):  # Flag length = 33 (including flag{...})
    expected_paths.append(u64(binary.read(dat_expected + i*8, 8)))

def find_char_for_path(target_path):
    # Try all printable ASCII characters
    for c in range(32, 127):
        current = 0
        # Follow the same tree traversal logic as in the binary
        while current != -1 and c != tree_nodes[current]:
            if c < tree_nodes[current]:
                current = current * 2 + 1
            elif c > tree_nodes[current]:
                current = (current + 1) * 2

        if current == target_path:
            return chr(c)
    return None

# Reconstruct the flag
flag = ""
for path in expected_paths:
    char = find_char_for_path(path)
    if char:
        flag += char
    else:
        print(f"Could not find character for path {path}")

print("Reconstructed flag:", flag)

#!/usr/bin/env python3
from pwn import *

# Load the binary
binary = ELF('./ctf_files/beleaf')

# Get base addresses
data_section = binary.get_section_by_name('.data')
dat_tree = data_section.header.sh_offset
dat_expected = dat_tree + 0x4c0  # Offset to expected paths

# Extract tree nodes and expected traversal results
tree_nodes = []
expected_paths = []

# Read tree nodes from .data section (array of ints)
tree_data = binary.read(data_section.header.sh_offset, 0x4c0)
for i in range(0, len(tree_data), 4):
    tree_nodes.append(u32(tree_data[i:i+4]))

# Read expected paths
expected_data = binary.read(data_section.header.sh_offset + 0x4c0, 33*8)
for i in range(0, len(expected_data), 8):
    expected_paths.append(u64(expected_data[i:i+8]))

def find_char_for_path(target_path):
    for c in range(32, 127):
        current = 0
        while True:
            if current == -1 or current >= len(tree_nodes):
                break
            if current == target_path and tree_nodes[current] == c:
                return chr(c)
            if c < tree_nodes[current]:
                current = current * 2 + 1
            elif c > tree_nodes[current]:
                current = (current + 1) * 2
            else:
                break
    return None

# Reconstruct the flag
flag = ""
for path in expected_paths:
    char = find_char_for_path(path)
    if char:
        flag += char
    else:
        print(f"Could not find character for path {path}")

print("Reconstructed flag:", flag)

# Verify flag format
if len(flag) == 33 and flag.startswith("flag{") and flag.endswith("}"):
    print("Flag format verification passed!")

