from pwn import *

# Load the binary
elf = ELF('./ctf_files/beleaf')

# Get the base addresses for our data sections
tree_base = elf.get_section_by_name('.data').header.sh_addr
tree_nodes = tree_base
expected_positions = tree_base + 0x4c0  # 003014e0 - 00301020

# Helper function to read tree nodes
def read_tree_node(addr):
    return u32(elf.read(addr, 4))

