from pwn import *

def traverse_tree(char, tree):
    pos = 0
    while pos < len(tree) and tree[pos] != 0:
        if char == tree[pos]:
            return pos
        if char < tree[pos]:
            pos = 2 * pos + 1
        else:
            pos = 2 * (pos + 1)
    return -1

# Load the binary
binary = open('./ctf_files/beleaf', 'rb').read()

# Extract tree nodes starting at 0x301020
tree_base = 0x301020
tree_nodes = []
for i in range(64):
    node_bytes = binary[tree_base + i*4:tree_base + (i+1)*4]
    if len(node_bytes) == 4:
        tree_nodes.append(u32(node_bytes))
    else:
        break

# Extract expected positions starting at 0x3014e0
expected_base = 0x3014e0
expected_pos = []
for i in range(33):  # Length of flag is 33
    pos_bytes = binary[expected_base + i*8:expected_base + (i+1)*8]
    if len(pos_bytes) == 8:
        expected_pos.append(u64(pos_bytes))
    else:
        break

# Find characters that lead to expected positions
flag = list('_' * 33)
for i, target_pos in enumerate(expected_pos):
    for c in range(32, 127):
        if traverse_tree(c, tree_nodes) == target_pos:
            flag[i] = chr(c)
            break

flag = ''.join(flag)
print(f"Found flag: {flag}")

# Verify flag format
if flag.startswith('flag{') and flag.endswith('}') and len(flag) == 33:
