#!/usr/bin/env python3
from pwn import *

# Load the binary
elf = ELF('./ctf_files/beleaf')

# Get the base addresses of the data sections
tree_base = elf.get_section_by_name('.data').header.sh_addr
tree_nodes = []
expected_pos = []

# Read tree nodes (32-bit integers)
for i in range(100):  # Read enough nodes to cover the tree
    try:
        node_offset = tree_base + 0x1020 - 0x301000 + i * 4
        tree_nodes.append(u32(elf.read(node_offset, 4)))
    except:
        break

# Read expected positions (64-bit integers)
for i in range(33):  # We need 33 chars (flag{...})
    try:
        pos_offset = tree_base + 0x14e0 - 0x301000 + i * 8
        expected_pos.append(u64(elf.read(pos_offset, 8)))
    except:
        break

def traverse(char):
    pos = 0
    while pos != -1 and char != tree_nodes[pos]:
        if char < tree_nodes[pos]:
            pos = pos * 2 + 1
        elif char > tree_nodes[pos]:
            pos = (pos + 1) * 2
    return pos

def find_char_for_position(target_pos):
    # Try all possible ASCII characters
    for c in range(32, 127):
        if traverse(c) == target_pos:
            return chr(c)
    return None

# Build the flag
flag = ""
for pos in expected_pos:
    char = find_char_for_position(pos)
    if char:
        flag += char

print(f"Flag: {flag}")

# Verify the flag
assert len(flag) == 33
assert flag.startswith("flag{")
assert flag.endswith("}")

