from pwn import *

def traverse_tree(tree, char):
    pos = 0
    while pos != -1 and char != tree[pos]:
        if char < tree[pos]:
            pos = pos * 2 + 1
        elif char > tree[pos]:
            pos = (pos + 1) * 2
    return pos

