    tree.append(u32(tree_data[i:i+4]))

# Convert expected positions to list
expected = []
for i in range(0, len(expected_pos), 8):
    expected.append(u64(expected_pos[i:i+8]))

# Reconstruct flag by trying all printable characters for each position
flag = ""
for pos in expected:
    # Try all printable ASCII characters
    for c in range(32, 127):
        if traverse_tree(tree, c) == pos:
            flag += chr(c)
            break

print("Flag found:", flag)

